.app-header h1 {
  font-size: 36px;
  margin: 0 0 10px 0;
  color: var(--text-h);
}

.subtitle {
  font-size: 16px;
  color: var(--text);
  margin: 0;
}

.feed-container {
  display: flex;
  flex-direction: column;
  gap: 30px;
}

.loading-state,
.error-state {
  text-align: center;
  padding: 40px;
  font-size: 18px;
  background: var(--code-bg);
  border-radius: 8px;
  border: 1px solid var(--border);
