.card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12px;
  color: var(--text);
  margin-bottom: 12px;
}

.card-id {
  font-family: var(--mono);
  background: var(--code-bg);
  padding: 2px 6px;
  border-radius: 4px;
}

.card-time {
  font-style: italic;
}

.card-title {
  font-size: 20px;
  margin: 0 0 10px 0;
  color: var(--text-h);
}

.card-content {
  font-size: 15px;
  line-height: 1.6;
  color: var(--text);
  margin: 0;
}

.feed-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 15px;
  margin-top: 20px;
}

.loading-more-indicator {
  font-size: 14px;
  color: var(--accent);
  font-style: italic;
}

.load-more-btn {
  font-size: 16px;
  font-weight: 600;
  padding: 12px 24px;
  border-radius: 6px;
  color: #fff;
  background: var(--accent);
  border: none;
  cursor: pointer;
  box-shadow: var(--shadow);
  transition: background-color 0.2s, transform 0.1s;
}

.load-more-btn:hover:not(:disabled) {
  background: #9333ea;
  transform: translateY(-1px);
}

.load-more-btn:active:not(:disabled) {
  transform: translateY(0);
}

.load-more-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.no-more-items {
  font-size: 15px;
  color: var(--text);
  font-style: italic;
  padding: 15px;
